import { MakeLogicType, actions, connect, kea, listeners, path } from 'kea'
import posthog from 'posthog-js'

import { teamLogic } from 'scenes/teamLogic'

import { TeamPublicType, TeamType } from '~/types'

export type TodayPrimaryDashboardPickerSource = 'edit' | 'empty'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPrimaryDashboardLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayPrimaryDashboardLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    primaryDashboardOpened: (dashboardId: number) => {
        dashboardId: number
    }
    primaryDashboardPickerOpened: (source: TodayPrimaryDashboardPickerSource) => {
        source: TodayPrimaryDashboardPickerSource
    }
    setPrimaryDashboard: (
        dashboardId: number | null,
        source: TodayPrimaryDashboardPickerSource
    ) => {
        dashboardId: number | null
        source: TodayPrimaryDashboardPickerSource
    }
}

export type todayPrimaryDashboardLogicType = MakeLogicType<
    todayPrimaryDashboardLogicValues,
    todayPrimaryDashboardLogicActions
>

export const todayPrimaryDashboardLogic = kea<todayPrimaryDashboardLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayPrimaryDashboardLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        primaryDashboardPickerOpened: (source: TodayPrimaryDashboardPickerSource) => ({ source }),
        setPrimaryDashboard: (dashboardId: number | null, source: TodayPrimaryDashboardPickerSource) => ({
            dashboardId,
            source,
        }),
        primaryDashboardOpened: (dashboardId: number) => ({ dashboardId }),
    }),
    listeners(({ actions, values }) => ({
        primaryDashboardPickerOpened: ({ source }) => {
            posthog.capture('today primary dashboard picker opened', {
                source,
                has_primary_dashboard: !!values.currentTeam?.primary_dashboard,
            })
        },
        setPrimaryDashboard: ({ dashboardId, source }) => {
            const previous = values.currentTeam?.primary_dashboard ?? null
            if (dashboardId === previous) {
                return
            }
            actions.updateCurrentTeam({ primary_dashboard: dashboardId })
            // pinned: analytics event name, shared with the dashboard choice modal
            posthog.capture('primary dashboard changed', {
                surface: 'today home',
                source,
                cleared: dashboardId === null,
                had_primary_dashboard: previous !== null,
            })
        },
        primaryDashboardOpened: ({ dashboardId }) => {
            posthog.capture('today primary dashboard opened', { dashboard_id: dashboardId })
        },
    })),
])
